//! Windows: embeds the app icon (`assets/app-icon.ico`, regenerated by `cargo xtask icon`)
//! and the version information (the product's name from `brand.toml`, the version from
//! Cargo) into the executable as resources — Explorer, the taskbar and the window's title
//! bar take the icon from there. Nothing to do for other targets.
//!
//! The icon is resource 1 (`platform-winit` loads it by that number for the windows).
//! Compiled with `rc.exe` (MSVC), `windres` (MinGW, cross-compiling included) or `llvm-rc`.

use std::path::Path;

fn main() {
    // Read when the script runs, not when it was built: the repository may have moved since.
    let dir = std::env::var_os("CARGO_MANIFEST_DIR").unwrap_or_default();
    let root = Path::new(&dir).join("../..");
    let icon = root.join("assets/app-icon.ico");
    let brand = root.join("brand.toml");
    println!("cargo:rerun-if-changed={}", icon.display());
    println!("cargo:rerun-if-changed={}", brand.display());
    println!("cargo:rerun-if-changed=build.rs");
    if std::env::var("CARGO_CFG_TARGET_OS").as_deref() != Ok("windows") {
        return;
    }

    let brand = std::fs::read_to_string(&brand)
        .unwrap_or_else(|e| panic!("brand.toml at the repository root: {e}"));
    let value = |key: &str| {
        brand
            .lines()
            .map(str::trim)
            .filter(|l| !l.starts_with('#'))
            .find_map(|l| {
                let (k, v) = l.split_once('=')?;
                (k.trim() == key).then(|| v.trim().trim_matches('"').to_owned())
            })
            .unwrap_or_else(|| panic!("brand.toml: missing `{key}`"))
    };
    let (name, id) = (value("name"), value("id"));
    let version = std::env::var("CARGO_PKG_VERSION").unwrap_or_else(|_| "0.0.0".into());
    // `1,2,3,0`: the numeric form (four 16-bit parts; anything after `-` or `+` dropped).
    let numeric = {
        let core = version.split(['-', '+']).next().unwrap_or_default();
        let mut parts: Vec<u16> = core.split('.').map(|p| p.parse().unwrap_or(0)).collect();
        parts.resize(4, 0);
        parts.iter().map(u16::to_string).collect::<Vec<_>>().join(",")
    };
    // Forward slashes: both `rc.exe` and `windres` take them, and no escaping is needed.
    let icon_path = icon
        .canonicalize()
        .unwrap_or_else(|e| panic!("{}: {e}", icon.display()))
        .to_string_lossy()
        .replace('\\', "/");
    let icon_path = icon_path.strip_prefix("//?/").unwrap_or(&icon_path);
    let quoted = |s: &str| s.replace('"', "\"\"");
    let (name, id) = (quoted(&name), quoted(&id));
    let rc = format!(
        r#"#pragma code_page(65001)
1 ICON "{icon_path}"

1 VERSIONINFO
FILEVERSION {numeric}
PRODUCTVERSION {numeric}
FILEOS 0x40004
FILETYPE 0x1
BEGIN
  BLOCK "StringFileInfo"
  BEGIN
    BLOCK "040904B0"
    BEGIN
      VALUE "FileDescription", "{name}"
      VALUE "FileVersion", "{version}"
      VALUE "InternalName", "{id}"
      VALUE "OriginalFilename", "{id}.exe"
      VALUE "ProductName", "{name}"
      VALUE "ProductVersion", "{version}"
    END
  END
  BLOCK "VarFileInfo"
  BEGIN
    VALUE "Translation", 0x409, 1200
  END
END
"#
    );
    let out_dir = std::env::var("OUT_DIR").unwrap_or_else(|e| panic!("OUT_DIR: {e}"));
    let out = Path::new(&out_dir).join("app.rc");
    std::fs::write(&out, rc).unwrap_or_else(|e| panic!("{}: {e}", out.display()));
    embed_resource::compile(&out, embed_resource::NONE)
        .manifest_required()
        .unwrap_or_else(|e| panic!("can't compile the Windows resources: {e}"));
}
